import{_ as e,a0 as l,w as o,s as d,I as t,x as n,a1 as p,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const q=JSON.parse('{"title":"使用 tqdm 在 Python 應用中顯示進度 | LCTT x X-CMD","titleTemplate":false,"description":"使用 tqdm 在 Python 應用中顯示進度 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 tqdm 在 Python 應用中顯示進度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 tqdm 在 Python 應用中顯示進度 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20201229 Show progress in your Python apps with tqdm","title":"使用 tqdm 在 Python 應用中顯示進度","tag":"202101","desc":""},"relativePath":"202101/20201229 Show progress in your Python apps with tqdm.md","filePath":"[post].md"}'),u={name:"202101/20201229 Show progress in your Python apps with tqdm.md"};function g(h,s,m,k,b,f){const a=l("Link");return o(),d("div",null,[s[30]||(s[30]=t("h1",{id:"使用-tqdm-在-python-應用中顯示進度",tabindex:"-1"},[n("使用 tqdm 在 Python 應用中顯示進度 "),t("a",{class:"header-anchor",href:"#使用-tqdm-在-python-應用中顯示進度","aria-label":"Permalink to “使用 tqdm 在 Python 應用中顯示進度”"},"​")],-1)),s[31]||(s[31]=t("blockquote",null,[t("p",null,"如果你的程序需要一段時間才能顯示結果，可通過顯示它的進度來避免讓用户感到沮喪。")],-1)),s[32]||(s[32]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202101/06/230842thi8skahe68dqa3m.jpg",alt:""})],-1)),s[33]||(s[33]=t("p",null,[n("阿拉米語，希伯來語和阿拉伯語中的閃米特語根 "),t("em",null,"q-d-m"),n(" 通常與前進或進度有關。阿拉伯語 "),t("em",null,"taqaddum"),n(" （تقدّم）的意思是“進度”。進度是很重要的。正如每部感覺良好的電影都會告訴你，旅程和目的地同樣重要。")],-1)),s[34]||(s[34]=t("p",null,"大多數程序都有一個明確的目標，一個期望的最終狀態。有時，計算這個最終狀態可能需要很長的時間。雖然計算機沒有感情不在乎，但人卻在乎。人類並不樂意坐在原地等待，而看不到任何明顯的進展跡象。疑問不斷蔓延。程序崩潰了嗎？磁盤性能是否抖動？操作系統是否把所有的計算資源都分配給了其他任務？",-1)),t("p",null,[s[1]||(s[1]=n("就像正義一樣，進度必須被看到，而不僅僅是完成。Python 庫 ",-1)),p(a,{href:"https://pypi.org/project/tqdm/"},{default:i(()=>[...s[0]||(s[0]=[n("tqdm",-1)])]),_:1}),s[2]||(s[2]=n(" 有助於使進度變得明確。",-1))]),t("p",null,[s[4]||(s[4]=t("code",null,"tqdm",-1)),s[5]||(s[5]=n(" 模組可在控制台下工作，但它也專門支持了我最喜歡的環境之一 Jupyter。要在 Jupyter 中使用 ",-1)),s[6]||(s[6]=t("code",null,"tqdm",-1)),s[7]||(s[7]=n("，你需要導入 ",-1)),s[8]||(s[8]=t("code",null,"notebook",-1)),s[9]||(s[9]=n(" 子模組並安裝 ",-1)),p(a,{href:"https://opensource.com/article/20/11/daily-journal-jupyter"},{default:i(()=>[...s[3]||(s[3]=[n("ipywidgets",-1)])]),_:1}),s[10]||(s[10]=n("。",-1)),s[11]||(s[11]=t("code",null,"notebook",-1)),s[12]||(s[12]=n(" 子模組與 ",-1)),s[13]||(s[13]=t("code",null,"tqdm",-1)),s[14]||(s[14]=n(" 接口兼容。",-1))]),s[35]||(s[35]=r(`<p>這意味着你可以做一些導入時操作來導入正確的模組，同時保持 <code>tqdm</code> 的用法不變。訣竅是檢查 <code>__main__</code> 模組是否具有全局變量 <code>get_ipython</code>。雖然這只是一個啓發式的方法，但卻是一個相當準確的方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import sys</span></span>
<span class="line"><span>if hasattr(sys.modules[&quot;__main__&quot;], &quot;get_ipython&quot;):</span></span>
<span class="line"><span>    from tqdm import notebook as tqdm</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    import tqdm</span></span></code></pre></div><p>最簡單的情況是，某件事情需要運行一定的迭代次數（事先已知），而每一次迭代的時間都差不多。例如，有一個計算任何數字的平方根的算法，通過從 1 作為猜測值開始，然後計算出一個改進後的猜測值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def improve_guess(rt, n):</span></span>
<span class="line"><span>    return (rt + n/rt) / 2</span></span></code></pre></div><p>一點點的改進可以讓你更加接近該平方根。例如，你可以計算 2 的平方根：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>guess = 1</span></span>
<span class="line"><span>target = 2</span></span>
<span class="line"><span>for i in tqdm.trange(10):</span></span>
<span class="line"><span>    guess = improve_guess(guess, target)</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/output_8_0.png" alt="tqdm output" title="tqdm output"></p><p>精確了到小數點後 10 位！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>round(2 - guess*guess, 10)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>0.0</span></span></code></pre></div><p>一個稍微複雜一點的例子是，當元素的數量是已知的，而處理每個元素需要類似的時間。例如，你可以計算一些數字的乘積。為此，你需要一些隨機數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import random</span></span>
<span class="line"><span>numbers = [random.uniform(0, 2.8) for i in range(100)]</span></span>
<span class="line"><span>numbers[:5]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[2.6575636572230916,</span></span>
<span class="line"><span>0.1286674965830302,</span></span>
<span class="line"><span>1.0634250104041332,</span></span>
<span class="line"><span>1.1760969844376505,</span></span>
<span class="line"><span>0.45192978568125486]</span></span></code></pre></div><p>現在有了這些數字，可以將它們相乘了。使用 <code>tqdm</code> 最簡單的方法是包裝一個 Python 迭代函數。數值是一樣的，但是 <code>tqdm</code> 會顯示一個進度條：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>result = 1</span></span>
<span class="line"><span>for num in tqdm.tqdm(numbers):</span></span>
<span class="line"><span>    result *= num</span></span>
<span class="line"><span>result</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2.4081854901728303</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/output_15_0.png" alt="tqdm output" title="tqdm output"></p><p>然而，並不是所有的事情都可以預測。最不容易預測的事情之一就是網絡速度。當你下載一個大文件時，衡量進度的唯一方法就是檢查已經下載了多少：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>url = &quot;https://www.python.org/ftp/python/3.9.0/Python-3.9.0.tgz&quot;</span></span>
<span class="line"><span>import httpx</span></span>
<span class="line"><span>with httpx.stream(&quot;GET&quot;, url) as response:</span></span>
<span class="line"><span>    total = int(response.headers[&quot;Content-Length&quot;])</span></span>
<span class="line"><span>    with tqdm.tqdm(total=total) as progress:</span></span>
<span class="line"><span>        for chunk in response.iter_bytes():</span></span>
<span class="line"><span>            progress.update(len(chunk))</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/output_18_0.png" alt="tqdm output" title="tqdm output"></p><p>有時，“嵌套”進度條是有意義的。例如，如果你要下載一個目錄，你就需要一個進度條來跟蹤文件，併為每個文件設置一個進度條。</p><p>下面是一個例子（但沒有實際下載一個目錄）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>files = [f&quot;vid-{i}.mp4&quot; for i in range(4)]</span></span>
<span class="line"><span>for fname in tqdm.tqdm(files, desc=&quot;files&quot;):</span></span>
<span class="line"><span>    total = random.randrange(10**9, 2 * 10**9)</span></span>
<span class="line"><span>    with tqdm.tqdm(total=total, desc=fname) as progress:</span></span>
<span class="line"><span>        current = 0</span></span>
<span class="line"><span>        while current &amp;lt; total:</span></span>
<span class="line"><span>            chunk_size = min(random.randrange(10**3, 10**5), total - current)</span></span>
<span class="line"><span>            current += chunk_size</span></span>
<span class="line"><span>            if random.uniform(0, 1) &amp;lt; 0.01:</span></span>
<span class="line"><span>                time.sleep(0.1)</span></span>
<span class="line"><span>            progress.update(chunk_size)</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/output_21_0.png" alt="tqdm output" title="tqdm output"></p><p>所以，如果你的程序需要一段時間才能顯示最終結果，為避免讓你的用户感到沮喪。請顯示它的進度！</p><hr>`,26)),t("p",null,[s[16]||(s[16]=n("via: ",-1)),p(a,{href:"https://opensource.com/article/20/12/tqdm-python"},{default:i(()=>[...s[15]||(s[15]=[n("https://opensource.com/article/20/12/tqdm-python",-1)])]),_:1})]),t("p",null,[s[21]||(s[21]=n("作者：",-1)),p(a,{href:"https://opensource.com/users/moshez"},{default:i(()=>[...s[17]||(s[17]=[n("Moshe Zadka",-1)])]),_:1}),s[22]||(s[22]=n(" 選題：",-1)),p(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[18]||(s[18]=[n("lujun9972",-1)])]),_:1}),s[23]||(s[23]=n(" 譯者：",-1)),p(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[19]||(s[19]=[n("geekpi",-1)])]),_:1}),s[24]||(s[24]=n(" 校對：",-1)),p(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[20]||(s[20]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[27]||(s[27]=n("本文由 ",-1)),p(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[25]||(s[25]=[n("LCTT",-1)])]),_:1}),s[28]||(s[28]=n(" 原創編譯，",-1)),p(a,{href:"https://linux.cn/"},{default:i(()=>[...s[26]||(s[26]=[n("Linux中國",-1)])]),_:1}),s[29]||(s[29]=n(" 榮譽推出",-1))])])}const C=e(u,[["render",g]]);export{q as __pageData,C as default};
